import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import {
  Button,
  FormActions,
  FormRowCol,
  FormSkeleton,
  Input,
  LabelMoney,
  MoneyInput,
  NumberInput,
  Select,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Text } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import type {
  CreateExpansionSimulationDto,
  ExpansionFormulaDto,
  ExpansionInvestLineDto,
  ExpansionSimulationDto,
} from '../../../services/fpc/types';
import styles from './ExpansionSimPage.module.css';

declare global {
  interface Window {
    __LINM_UPDATE_TAB_TITLE__?: (title: string) => void;
    __LINM_IS_CURRENT_TAB_DIRTY__?: boolean;
  }
}

const TEST_ID = 'expansion-sim';

type FormMode = 'create' | 'edit' | 'view';

type SystemKey =
  | 'capexFitOut'
  | 'capexEquipment'
  | 'preOpeningCost'
  | 'workingCapitalRequired'
  | 'initialInventoryValue';

interface InvestLine {
  clientId: string;
  systemKey?: SystemKey | null;
  label: string;
  amount: number;
  note: string;
}

interface HeaderState {
  name: string;
  projectedMonthlyRevenue: number;
  targetGrossMarginPercent: number;
  monthlyFixedCosts: number;
  rampUpMonths: number;
  rampUpRevenuePercent: number;
  breakEvenFormulaCode: string;
  paybackFormulaCode: string;
  recommendationFormulaCode: string;
}

const INVEST_DEFS: { key: SystemKey; label: string }[] = [
  { key: 'capexFitOut', label: 'Vốn fit-out' },
  { key: 'capexEquipment', label: 'Vốn thiết bị' },
  { key: 'preOpeningCost', label: 'Chi phí trước khai trương' },
  { key: 'workingCapitalRequired', label: 'Vốn lưu động yêu cầu' },
  { key: 'initialInventoryValue', label: 'Hàng tồn kho ban đầu' },
];

const emptyHeader = (): HeaderState => ({
  name: '',
  projectedMonthlyRevenue: 0,
  targetGrossMarginPercent: 40,
  monthlyFixedCosts: 0,
  rampUpMonths: 3,
  rampUpRevenuePercent: 50,
  breakEvenFormulaCode: '',
  paybackFormulaCode: '',
  recommendationFormulaCode: '',
});

const newClientId = (): string =>
  `L-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

const seedLines = (amounts?: Partial<Record<SystemKey, number>>): InvestLine[] =>
  INVEST_DEFS.map(d => ({
    clientId: newClientId(),
    systemKey: d.key,
    label: d.label,
    amount: amounts?.[d.key] ?? 0,
    note: '',
  }));

function linesFromDto(d: ExpansionSimulationDto): InvestLine[] {
  if (d.lines && d.lines.length > 0) {
    return [...d.lines]
      .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0))
      .map(l => ({
        clientId: l.id || newClientId(),
        systemKey: (l.systemKey as SystemKey | null | undefined) ?? null,
        label: l.label || '',
        amount: l.amount ?? 0,
        note: l.note ?? '',
      }));
  }
  return seedLines({
    capexFitOut: d.capexFitOut,
    capexEquipment: d.capexEquipment,
    preOpeningCost: d.preOpeningCost,
    workingCapitalRequired: d.workingCapitalRequired,
    initialInventoryValue: d.initialInventoryValue,
  });
}

function dtoToState(d: ExpansionSimulationDto): { header: HeaderState; lines: InvestLine[] } {
  return {
    header: {
      name: d.name ?? '',
      projectedMonthlyRevenue: d.projectedMonthlyRevenue ?? 0,
      targetGrossMarginPercent: d.targetGrossMarginPercent ?? 0,
      monthlyFixedCosts: d.monthlyFixedCosts ?? 0,
      rampUpMonths: d.rampUpMonths ?? 3,
      rampUpRevenuePercent: d.rampUpRevenuePercent ?? 50,
      breakEvenFormulaCode: d.breakEvenFormulaCode ?? '',
      paybackFormulaCode: d.paybackFormulaCode ?? '',
      recommendationFormulaCode: d.recommendationFormulaCode ?? '',
    },
    lines: linesFromDto(d),
  };
}

function toLinePayload(lines: InvestLine[]): ExpansionInvestLineDto[] {
  return lines.map((l, i) => ({
    systemKey: l.systemKey || null,
    label: l.label.trim(),
    amount: l.amount || 0,
    note: l.note.trim() || null,
    sortOrder: i,
  }));
}

function amountBySystemKey(lines: InvestLine[], key: SystemKey): number {
  return lines.filter(l => l.systemKey === key).reduce((s, l) => s + (l.amount || 0), 0);
}

function toCreateDto(header: HeaderState, lines: InvestLine[]): CreateExpansionSimulationDto {
  return {
    name: header.name.trim(),
    capexFitOut: amountBySystemKey(lines, 'capexFitOut'),
    capexEquipment: amountBySystemKey(lines, 'capexEquipment'),
    preOpeningCost: amountBySystemKey(lines, 'preOpeningCost'),
    workingCapitalRequired: amountBySystemKey(lines, 'workingCapitalRequired'),
    initialInventoryValue: amountBySystemKey(lines, 'initialInventoryValue'),
    projectedMonthlyRevenue: header.projectedMonthlyRevenue,
    targetGrossMarginPercent: header.targetGrossMarginPercent,
    monthlyFixedCosts: header.monthlyFixedCosts,
    rampUpMonths: header.rampUpMonths,
    rampUpRevenuePercent: header.rampUpRevenuePercent,
    breakEvenFormulaCode: header.breakEvenFormulaCode || null,
    paybackFormulaCode: header.paybackFormulaCode || null,
    recommendationFormulaCode: header.recommendationFormulaCode || null,
    lines: toLinePayload(lines),
  };
}

function formulaOptions(list: ExpansionFormulaDto[]): { value: string; label: string }[] {
  return list
    .filter(f => f.isActive)
    .map(f => ({
      value: f.code,
      label: f.isDefault ? `${f.name} (mặc định)` : f.name,
    }));
}

const fVnd = (v?: number | null): string => {
  if (v == null) return '—';
  return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);
};

const RequiredMark: React.FC = () => (
  <span className={styles.requiredMark} aria-hidden="true">*</span>
);

function isLineRowFieldTarget(target: HTMLElement): boolean {
  return !!target.closest(
    'input, textarea, select, button, a, [role="option"], [role="listbox"], [data-search-dropdown], label',
  );
}

const ExpansionSimPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const isNew = !id || id === 'new';
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { canViewExpansionSimulator, canRunExpansionSimulator } = useFpcPermissions();

  const [mode, setMode] = useState<FormMode>(isNew ? 'create' : 'edit');
  const [header, setHeader] = useState<HeaderState>(emptyHeader);
  const [lines, setLines] = useState<InvestLine[]>(() => seedLines());
  const [selectedLineIndex, setSelectedLineIndex] = useState(0);
  const [headerExpanded, setHeaderExpanded] = useState(true);
  const [result, setResult] = useState<ExpansionSimulationDto | null>(null);
  const [formulas, setFormulas] = useState<ExpansionFormulaDto[]>([]);
  const [loading, setLoading] = useState(!isNew);
  const [saving, setSaving] = useState(false);
  const [running, setRunning] = useState(false);
  const [snapshot, setSnapshot] = useState('');

  const bepOptions = useMemo(
    () => formulaOptions(formulas.filter(f => f.formulaKind === 'BreakEven')),
    [formulas],
  );
  const pbOptions = useMemo(
    () => formulaOptions(formulas.filter(f => f.formulaKind === 'Payback')),
    [formulas],
  );
  const recOptions = useMemo(
    () => formulaOptions(formulas.filter(f => f.formulaKind === 'Recommendation')),
    [formulas],
  );

  const editMode = mode === 'create' || mode === 'edit';
  const readOnly = !editMode || !canRunExpansionSimulator;

  const totalInvestment = useMemo(
    () => lines.reduce((s, l) => s + (l.amount || 0), 0),
    [lines],
  );

  const patchHeader = <K extends keyof HeaderState>(key: K, value: HeaderState[K]) => {
    setHeader(prev => ({ ...prev, [key]: value }));
  };

  const patchLine = (index: number, patch: Partial<InvestLine>) => {
    setLines(prev => prev.map((l, i) => (i === index ? { ...l, ...patch } : l)));
  };

  const handleAddLine = () => {
    setLines(prev => {
      const next: InvestLine = {
        clientId: newClientId(),
        systemKey: null,
        label: '',
        amount: 0,
        note: '',
      };
      setSelectedLineIndex(prev.length);
      return [...prev, next];
    });
  };

  const handleCopyLine = () => {
    if (selectedLineIndex < 0 || selectedLineIndex >= lines.length) return;
    const src = lines[selectedLineIndex];
    setLines(prev => {
      const copy: InvestLine = {
        ...src,
        clientId: newClientId(),
        systemKey: null,
        label: src.label ? `${src.label} (copy)` : '',
      };
      const next = [...prev];
      next.splice(selectedLineIndex + 1, 0, copy);
      setSelectedLineIndex(selectedLineIndex + 1);
      return next;
    });
  };

  const handleDeleteLine = () => {
    if (lines.length <= 1) {
      dispatchAppToast(dispatch, { message: 'Cần ít nhất 1 dòng vốn đầu tư', type: 'info' });
      return;
    }
    if (selectedLineIndex < 0 || selectedLineIndex >= lines.length) return;
    setLines(prev => {
      const next = prev.filter((_, i) => i !== selectedLineIndex);
      setSelectedLineIndex(Math.min(selectedLineIndex, next.length - 1));
      return next;
    });
  };

  const load = useCallback(async (simId: string) => {
    setLoading(true);
    try {
      const dto = await fpcService.getExpansionSimById(simId);
      const state = dtoToState(dto);
      setHeader(state.header);
      setLines(state.lines);
      setResult(dto);
      setMode(dto.status === 'Completed' ? 'view' : 'edit');
      setSnapshot(JSON.stringify({ header: state.header, lines: state.lines }));
    } catch {
      dispatchAppToast(dispatch, { message: 'Không tải được chứng từ mô phỏng', type: 'error' });
      navigate('/tc/kh/mo-rong-ch');
    } finally {
      setLoading(false);
    }
  }, [dispatch, navigate]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void (async () => {
        try {
          const list = await fpcService.getExpansionFormulaList();
          setFormulas(list ?? []);
          if (isNew) {
            setHeader(prev => {
              const pick = (kind: string) =>
                list?.find((f: ExpansionFormulaDto) => f.formulaKind === kind && f.isDefault)?.code
                || list?.find((f: ExpansionFormulaDto) => f.formulaKind === kind)?.code
                || '';
              return {
                ...prev,
                breakEvenFormulaCode: prev.breakEvenFormulaCode || pick('BreakEven'),
                paybackFormulaCode: prev.paybackFormulaCode || pick('Payback'),
                recommendationFormulaCode: prev.recommendationFormulaCode || pick('Recommendation'),
              };
            });
          }
        } catch {
          setFormulas([]);
        }
      })();
    }, 0);
    return () => window.clearTimeout(t);
  }, [isNew]);

  useEffect(() => {
    if (isNew) {
      setSnapshot(JSON.stringify({ header: emptyHeader(), lines: seedLines() }));
      return;
    }
    const t = window.setTimeout(() => { void load(id!); }, 0);
    return () => window.clearTimeout(t);
  }, [id, isNew, load]);

  useEffect(() => {
    const title = isNew
      ? 'Tạo mô phỏng mở rộng'
      : (header.name ? `Mở rộng: ${header.name}` : 'Mô phỏng mở rộng');
    window.__LINM_UPDATE_TAB_TITLE__?.(title);
  }, [header.name, isNew]);

  useEffect(() => {
    window.__LINM_IS_CURRENT_TAB_DIRTY__ = editMode
      && JSON.stringify({ header, lines }) !== snapshot;
    return () => { window.__LINM_IS_CURRENT_TAB_DIRTY__ = false; };
  }, [editMode, header, lines, snapshot]);

  const validate = (): string | null => {
    if (!header.name.trim()) return 'Vui lòng nhập tên mô phỏng';
    if (header.targetGrossMarginPercent < 0 || header.targetGrossMarginPercent > 100) {
      return 'Biên lãi gộp phải trong 0–100%';
    }
    if (lines.some(l => !l.label.trim())) return 'Vui lòng nhập tên khoản mục trên mọi dòng';
    return null;
  };

  const handleCancel = () => {
    if (isNew) {
      navigate('/tc/kh/mo-rong-ch');
      return;
    }
    void load(id!);
  };

  const handleSave = async () => {
    const err = validate();
    if (err) {
      dispatchAppToast(dispatch, { message: err, type: 'error' });
      return;
    }
    setSaving(true);
    try {
      const dto = toCreateDto(header, lines);
      if (isNew) {
        const created = await fpcService.createExpansionSim(dto);
        dispatchAppToast(dispatch, { message: 'Đã tạo mô phỏng mở rộng', type: 'success' });
        navigate(`/tc/kh/mo-rong-ch/${created.id}`, { replace: true });
      } else {
        const updated = await fpcService.updateExpansionSim(id!, dto);
        const state = dtoToState(updated);
        setHeader(state.header);
        setLines(state.lines);
        setResult(updated);
        setSnapshot(JSON.stringify({ header: state.header, lines: state.lines }));
        dispatchAppToast(dispatch, { message: 'Đã lưu mô phỏng', type: 'success' });
      }
    } catch {
      dispatchAppToast(dispatch, { message: 'Lưu thất bại', type: 'error' });
    } finally {
      setSaving(false);
    }
  };

  const handleRun = async () => {
    if (isNew) {
      dispatchAppToast(dispatch, { message: 'Lưu chứng từ trước khi chạy mô phỏng', type: 'error' });
      return;
    }
    setRunning(true);
    try {
      if (editMode && canRunExpansionSimulator) {
        const err = validate();
        if (err) {
          dispatchAppToast(dispatch, { message: err, type: 'error' });
          setRunning(false);
          return;
        }
        await fpcService.updateExpansionSim(id!, toCreateDto(header, lines));
      }
      const ran = await fpcService.runExpansionSim(id!);
      const state = dtoToState(ran);
      setResult(ran);
      setHeader(state.header);
      setLines(state.lines);
      setMode('view');
      setSnapshot(JSON.stringify({ header: state.header, lines: state.lines }));
      dispatchAppToast(dispatch, { message: 'Đã chạy mô phỏng', type: 'success' });
    } catch {
      dispatchAppToast(dispatch, { message: 'Chạy mô phỏng thất bại', type: 'error' });
    } finally {
      setRunning(false);
    }
  };

  const handleSelectLine = (idx: number, e: React.MouseEvent) => {
    setSelectedLineIndex(idx);
    if (isLineRowFieldTarget(e.target as HTMLElement)) return;
  };

  if (!canViewExpansionSimulator) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.pageFormScroll}>
          <Text type="secondary">Bạn không có quyền xem mô phỏng mở rộng.</Text>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className={styles.page} data-form-page data-voucher-form-shell data-testid={`${TEST_ID}-page`}>
        <div className={styles.pageFormScroll}>
          <FormSkeleton headerRows={2} lineRows={5} data-testid={`${TEST_ID}-form-skeleton`} />
        </div>
      </div>
    );
  }

  const pageTitle = isNew
    ? 'Tạo mô phỏng mở rộng'
    : (header.name ? `Mô phỏng: ${header.name}` : 'Mô phỏng mở rộng');

  return (
    <div className={styles.page} data-form-page data-voucher-form-shell data-testid={`${TEST_ID}-page`}>
      <div className={styles.pageFormHeader}>
        <div className={styles.stickyTop}>
          <div className={styles.pageHeader}>
            <div className={styles.toolbarRow}>
              <button
                className={styles.backBtn}
                type="button"
                onClick={() => navigate('/tc/kh/mo-rong-ch')}
                data-testid={`${TEST_ID}-back-btn`}
              >
                <i className="fas fa-arrow-left" aria-hidden /> Quay lại
              </button>
              <FormActions align="end">
                {editMode ? (
                  <>
                    <Button onClick={handleCancel} data-testid={`${TEST_ID}-cancel-btn`}>
                      <i className="fas fa-times" /> Hủy
                    </Button>
                    <Button
                      variant="primary"
                      disabled={saving}
                      onClick={() => void handleSave()}
                      data-testid={`${TEST_ID}-save-btn`}
                    >
                      <i className={`fas ${saving ? 'fa-spinner fa-spin' : 'fa-save'}`} />
                      {saving ? ' Đang lưu…' : ' Lưu'}
                    </Button>
                    {canRunExpansionSimulator && !isNew && (
                      <Button
                        variant="primary"
                        disabled={running}
                        onClick={() => void handleRun()}
                        data-testid={`${TEST_ID}-run-btn`}
                      >
                        <i className="fas fa-play" /> {running ? 'Đang chạy…' : 'Chạy mô phỏng'}
                      </Button>
                    )}
                  </>
                ) : (
                  <>
                    {canRunExpansionSimulator && (
                      <Button
                        variant="primary"
                        onClick={() => setMode('edit')}
                        data-testid={`${TEST_ID}-edit-btn`}
                      >
                        <i className="fas fa-edit" /> Sửa
                      </Button>
                    )}
                    {canRunExpansionSimulator && (
                      <Button
                        variant="primary"
                        disabled={running}
                        onClick={() => void handleRun()}
                        data-testid={`${TEST_ID}-run-btn`}
                      >
                        <i className="fas fa-play" /> {running ? 'Đang chạy…' : 'Chạy mô phỏng'}
                      </Button>
                    )}
                    <Button onClick={() => window.print()} data-testid={`${TEST_ID}-print-btn`}>
                      <i className="fas fa-print" /> In
                    </Button>
                  </>
                )}
              </FormActions>
            </div>
            <h1 className={styles.title}>{pageTitle}</h1>
            {!editMode && (
              <div className={styles.viewModeHint} data-testid={`${TEST_ID}-view-hint`}>
                <i className="fas fa-eye" /> Chế độ xem — nhấn <strong>Sửa</strong> để chỉnh sửa
              </div>
            )}
            {editMode && (
              <div className={styles.readOnlyHint} data-testid={`${TEST_ID}-edit-hint`}>
                <i className="fas fa-pen" /> Đang {isNew ? 'tạo mới' : 'chỉnh sửa'} — Lưu hoặc Hủy
              </div>
            )}
          </div>
        </div>
      </div>

      <div
        className={`${styles.pageFormScroll}${!editMode ? ` ${styles.viewDisabled}` : ''}`}
        id={`${TEST_ID}-content`}
      >
        <div className={styles.section} data-testid={`${TEST_ID}-section-header`}>
          <div className={styles.sectionTitleRow}>
            <h2 className={styles.sectionTitle}>THÔNG TIN CHỨNG TỪ</h2>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span className={styles.sectionBadge}>{result?.status || 'Draft'}</span>
              <button
                type="button"
                className={styles.headerToggleBtn}
                data-testid={`${TEST_ID}-header-${headerExpanded ? 'collapse' : 'expand'}`}
                aria-expanded={headerExpanded}
                onClick={() => setHeaderExpanded(v => !v)}
              >
                <span className={styles.headerToggleIcon} aria-hidden>
                  <i className={headerExpanded ? 'fas fa-chevron-up' : 'fas fa-chevron-down'} />
                </span>
                {headerExpanded ? 'Thu gọn' : 'Mở rộng'}
              </button>
            </div>
          </div>

          <FormRowCol cols={1} data-testid={`${TEST_ID}-name-label`}>
            <FormRowCol.Item>
              <label className={styles.label}>Tên mô phỏng<RequiredMark /></label>
            </FormRowCol.Item>
          </FormRowCol>
          <FormRowCol cols={1} data-testid={`${TEST_ID}-name-input`}>
            <FormRowCol.Item variant="field">
              <Input
                value={header.name}
                disabled={readOnly}
                onChange={e => patchHeader('name', e.target.value)}
                data-testid={`${TEST_ID}-name`}
              />
            </FormRowCol.Item>
          </FormRowCol>

          {headerExpanded && (
            <div className={styles.assumptionsGrid} data-testid={`${TEST_ID}-assumptions`}>
              <div className={styles.assumptionsCell}>
                <label className={styles.label}>Doanh thu tháng dự kiến<RequiredMark /></label>
                <MoneyInput
                  value={header.projectedMonthlyRevenue}
                  disabled={readOnly}
                  onChange={v => patchHeader('projectedMonthlyRevenue', v ?? 0)}
                  data-testid={`${TEST_ID}-revenue`}
                />
              </div>
              <div className={styles.assumptionsCell}>
                <label className={styles.label}>Biên lãi gộp (%)<RequiredMark /></label>
                <NumberInput
                  value={header.targetGrossMarginPercent}
                  readOnly={readOnly}
                  onChange={v => patchHeader('targetGrossMarginPercent', Number.isFinite(v) ? v : 0)}
                  data-testid={`${TEST_ID}-gm`}
                />
              </div>
              <div className={styles.assumptionsCell}>
                <label className={styles.label}>Chi phí cố định tháng<RequiredMark /></label>
                <MoneyInput
                  value={header.monthlyFixedCosts}
                  disabled={readOnly}
                  onChange={v => patchHeader('monthlyFixedCosts', v ?? 0)}
                  data-testid={`${TEST_ID}-fixed`}
                />
              </div>
              <div className={styles.assumptionsCell}>
                <label className={styles.label}>Số tháng ramp-up</label>
                <NumberInput
                  value={header.rampUpMonths}
                  readOnly={readOnly}
                  onChange={v => patchHeader('rampUpMonths', Number.isFinite(v) ? v : 0)}
                  data-testid={`${TEST_ID}-ramp-months`}
                />
              </div>
              <div className={styles.assumptionsCell}>
                <label className={styles.label}>% doanh thu ramp-up</label>
                <NumberInput
                  value={header.rampUpRevenuePercent}
                  readOnly={readOnly}
                  onChange={v => patchHeader('rampUpRevenuePercent', Number.isFinite(v) ? v : 0)}
                  data-testid={`${TEST_ID}-ramp-pct`}
                />
              </div>
            </div>
          )}

          <div className={styles.formulaRow} data-testid={`${TEST_ID}-formulas`}>
            <div className={styles.assumptionsCell}>
              <label className={styles.label}>Công thức hòa vốn</label>
              <Select
                value={header.breakEvenFormulaCode}
                disabled={readOnly}
                options={bepOptions}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                  patchHeader('breakEvenFormulaCode', e.target.value)}
                data-testid={`${TEST_ID}-bep-formula`}
              />
            </div>
            <div className={styles.assumptionsCell}>
              <label className={styles.label}>Công thức hoàn vốn</label>
              <Select
                value={header.paybackFormulaCode}
                disabled={readOnly}
                options={pbOptions}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                  patchHeader('paybackFormulaCode', e.target.value)}
                data-testid={`${TEST_ID}-pb-formula`}
              />
            </div>
            <div className={styles.assumptionsCell}>
              <label className={styles.label}>Công thức khuyến nghị</label>
              <Select
                value={header.recommendationFormulaCode}
                disabled={readOnly}
                options={recOptions}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                  patchHeader('recommendationFormulaCode', e.target.value)}
                data-testid={`${TEST_ID}-rec-formula`}
              />
            </div>
          </div>
        </div>

        <div className={styles.section} data-testid={`${TEST_ID}-section-lines`}>
          <div className={styles.sectionTitleRow}>
            <h2 className={styles.sectionTitle}>CHI TIẾT VỐN ĐẦU TƯ</h2>
            <span className={styles.sectionBadge}>{lines.length} dòng</span>
          </div>

          <div className={styles.tableWrapper}>
            <table className={styles.linesTable} data-testid={`${TEST_ID}-lines-table`}>
              <colgroup>
                <col className={styles.thStt} />
                <col className={styles.thLabel} />
                <col className={styles.thAmount} />
                <col className={styles.thNote} />
              </colgroup>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Khoản mục</th>
                  <th>Số tiền</th>
                  <th>Ghi chú</th>
                </tr>
              </thead>
              <tbody>
                {lines.map((line, idx) => (
                  <tr
                    key={line.clientId}
                    className={`${styles.lineRow}${selectedLineIndex === idx ? ` ${styles.lineRowSelected}` : ''}`}
                    onClick={e => handleSelectLine(idx, e)}
                    data-testid={`${TEST_ID}-line-${idx}`}
                  >
                    <td className={styles.colCenter}>{idx + 1}</td>
                    <td className={styles.colLabel}>
                      <Input
                        value={line.label}
                        disabled={readOnly}
                        onChange={e => patchLine(idx, { label: e.target.value })}
                        data-testid={`${TEST_ID}-line-${idx}-label`}
                      />
                    </td>
                    <td className={styles.tdAmount}>
                      <MoneyInput
                        className={styles.lineInput}
                        value={line.amount}
                        disabled={readOnly}
                        onChange={v => patchLine(idx, { amount: v ?? 0 })}
                        data-testid={`${TEST_ID}-line-${idx}-amount`}
                      />
                    </td>
                    <td className={styles.tdNote}>
                      <Input
                        value={line.note}
                        disabled={readOnly}
                        onChange={e => patchLine(idx, { note: e.target.value })}
                        data-testid={`${TEST_ID}-line-${idx}-note`}
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {editMode && (
            <div className={styles.linesActions}>
              <button
                type="button"
                className={styles.btnAddLine}
                data-testid={`${TEST_ID}-add-line-btn`}
                onClick={handleAddLine}
              >
                + Thêm dòng
              </button>
              <button
                type="button"
                className={styles.btnCopyLine}
                data-testid={`${TEST_ID}-copy-line-btn`}
                disabled={selectedLineIndex < 0}
                onClick={handleCopyLine}
              >
                Sao chép dòng
              </button>
              <button
                type="button"
                className={styles.btnCopyLine}
                data-testid={`${TEST_ID}-delete-line-btn`}
                disabled={selectedLineIndex < 0 || lines.length <= 1}
                onClick={handleDeleteLine}
              >
                Xóa dòng
              </button>
            </div>
          )}
        </div>

        <div className={styles.section} data-testid={`${TEST_ID}-section-result`}>
          <div className={styles.sectionTitleRow}>
            <h2 className={styles.sectionTitle}>KẾT QUẢ MÔ PHỎNG</h2>
            <span className={styles.sectionBadge}>
              {result?.status === 'Completed' ? 'Đã chạy' : 'Chưa chạy / Draft'}
            </span>
          </div>
          {!result || result.status !== 'Completed' ? (
            <Text type="secondary">
              Lưu rồi bấm «Chạy mô phỏng» để tính hòa vốn / hoàn vốn / khuyến nghị.
            </Text>
          ) : (
            <>
              <div className={styles.resultGrid}>
                <div className={styles.resultCard}>
                  <span className={styles.resultLabel}>Tổng đầu tư</span>
                  <span className={styles.resultValue}>{fVnd(result.totalInvestment)}</span>
                </div>
                <div className={styles.resultCard}>
                  <span className={styles.resultLabel}>Hòa vốn</span>
                  <span className={`${styles.resultValue} ${styles.positive}`}>
                    {result.breakEvenMonth != null ? `${result.breakEvenMonth} tháng` : '—'}
                  </span>
                </div>
                <div className={styles.resultCard}>
                  <span className={styles.resultLabel}>Hoàn vốn</span>
                  <span className={`${styles.resultValue} ${styles.positive}`}>
                    {result.paybackMonths != null ? `${result.paybackMonths} tháng` : '—'}
                  </span>
                </div>
                <div className={styles.resultCard}>
                  <span className={styles.resultLabel}>DT thuần/tháng</span>
                  <span className={styles.resultValue}>{fVnd(result.monthlyNetCashflow)}</span>
                </div>
                <div className={styles.resultCard}>
                  <span className={styles.resultLabel}>LN 12 tháng</span>
                  <span className={styles.resultValue}>{fVnd(result.twelveMonthProfit)}</span>
                </div>
                <div className={styles.resultCard}>
                  <span className={styles.resultLabel}>Ảnh hưởng runway</span>
                  <span className={`${styles.resultValue} ${styles.warning}`}>
                    {result.runwayImpactMonths != null ? `${result.runwayImpactMonths} tháng` : '—'}
                  </span>
                </div>
              </div>
              {result.recommendation && (
                <div className={styles.recommendRow}>
                  <i className="fas fa-lightbulb" style={{ color: '#f59e0b' }} />
                  <span><strong>Khuyến nghị:</strong> {result.recommendation}</span>
                </div>
              )}
            </>
          )}
        </div>
      </div>

      <div className={styles.pageFormFooter}>
        <div className={styles.footer}>
          <div className={styles.footerLeft}>
            <span className={styles.footerLabel}>Mô phỏng mở rộng CH</span>
            {result?.status && (
              <span className={styles.sectionBadge}>{result.status}</span>
            )}
          </div>
          <div className={styles.totalBlock}>
            <LabelMoney
              label="Tổng vốn đầu tư:"
              value={totalInvestment}
              variant="footer"
              emphasize
              data-testid={`${TEST_ID}-footer-total`}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default ExpansionSimPage;
